import{_ as l,c as i,o as e,ag as o}from"./chunks/framework.dvv-DFtf.js";const p=JSON.parse('{"title":"Notion 设计师项目管理模板","description":"","frontmatter":{"title":"Notion 设计师项目管理模板","layout":"page"},"headers":[],"relativePath":"resources/notion.md","filePath":"resources/notion.md"}'),t={name:"resources/notion.md"};function r(n,a,h,s,u,d){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="notion-设计师项目管理模板" tabindex="-1">Notion 设计师项目管理模板 <a class="header-anchor" href="#notion-设计师项目管理模板" aria-label="Permalink to &quot;Notion 设计师项目管理模板&quot;">​</a></h1><h2 id="模板介绍" tabindex="-1">模板介绍 <a class="header-anchor" href="#模板介绍" aria-label="Permalink to &quot;模板介绍&quot;">​</a></h2><p>专为设计师打造的 Notion 项目管理模板，帮助你高效管理设计项目、客户和灵感。</p><h3 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h3><ul><li>📋 项目看板管理</li><li>👥 客户关系管理</li><li>💡 灵感库 &amp; Moodboard</li><li>📅 时间跟踪系统</li><li>💰 报价单生成</li><li>📊 数据统计面板</li></ul><h2 id="模板结构" tabindex="-1">模板结构 <a class="header-anchor" href="#模板结构" aria-label="Permalink to &quot;模板结构&quot;">​</a></h2><h3 id="_1-项目管理" tabindex="-1">1. 项目管理 <a class="header-anchor" href="#_1-项目管理" aria-label="Permalink to &quot;1. 项目管理&quot;">​</a></h3><p><strong>看板视图</strong>：</p><ul><li>待开始 → 进行中 → 审核中 → 已完成</li></ul><p><strong>项目属性</strong>：</p><ul><li>项目名称、客户、截止日期</li><li>优先级、状态、标签</li><li>预算、实际成本</li></ul><h3 id="_2-客户管理" tabindex="-1">2. 客户管理 <a class="header-anchor" href="#_2-客户管理" aria-label="Permalink to &quot;2. 客户管理&quot;">​</a></h3><p>记录客户信息：</p><ul><li>基本信息（联系方式、公司）</li><li>合作历史</li><li>沟通记录</li><li>待办事项</li></ul><h3 id="_3-灵感库" tabindex="-1">3. 灵感库 <a class="header-anchor" href="#_3-灵感库" aria-label="Permalink to &quot;3. 灵感库&quot;">​</a></h3><p>收集设计灵感：</p><ul><li>图片画廊视图</li><li>标签分类（配色、排版、UI等）</li><li>来源链接</li><li>笔记备注</li></ul><h3 id="_4-时间跟踪" tabindex="-1">4. 时间跟踪 <a class="header-anchor" href="#_4-时间跟踪" aria-label="Permalink to &quot;4. 时间跟踪&quot;">​</a></h3><p>记录工作时长：</p><ul><li>项目计时器</li><li>每日时间日志</li><li>月度统计报表</li><li>时薪计算</li></ul><h3 id="_5-文档资源" tabindex="-1">5. 文档资源 <a class="header-anchor" href="#_5-文档资源" aria-label="Permalink to &quot;5. 文档资源&quot;">​</a></h3><p>存储常用资源：</p><ul><li>设计规范文档</li><li>合同模板</li><li>报价单模板</li><li>常用链接</li></ul><h2 id="下载使用" tabindex="-1">下载使用 <a class="header-anchor" href="#下载使用" aria-label="Permalink to &quot;下载使用&quot;">​</a></h2><p><strong>Notion 模板链接</strong>：<a href="https://notion.so/templates/designer-pm" target="_blank" rel="noreferrer">立即复制</a></p><p><strong>使用步骤</strong>：</p><ol><li>点击上方链接打开模板</li><li>点击右上角&quot;Duplicate&quot;</li><li>模板会复制到你的 Notion 工作区</li><li>开始自定义使用！</li></ol><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><h3 id="创建第一个项目" tabindex="-1">创建第一个项目 <a class="header-anchor" href="#创建第一个项目" aria-label="Permalink to &quot;创建第一个项目&quot;">​</a></h3><ol><li>进入&quot;项目管理&quot;页面</li><li>点击&quot;+ New&quot;创建项目</li><li>填写项目信息</li><li>拖动卡片到&quot;进行中&quot;</li></ol><h3 id="添加客户信息" tabindex="-1">添加客户信息 <a class="header-anchor" href="#添加客户信息" aria-label="Permalink to &quot;添加客户信息&quot;">​</a></h3><ol><li>进入&quot;客户管理&quot;数据库</li><li>添加新客户</li><li>关联到对应项目</li></ol><h3 id="收集灵感" tabindex="-1">收集灵感 <a class="header-anchor" href="#收集灵感" aria-label="Permalink to &quot;收集灵感&quot;">​</a></h3><ol><li>安装 Notion Web Clipper 插件</li><li>浏览网页时一键保存</li><li>自动添加到灵感库</li></ol><h2 id="自定义技巧" tabindex="-1">自定义技巧 <a class="header-anchor" href="#自定义技巧" aria-label="Permalink to &quot;自定义技巧&quot;">​</a></h2><h3 id="修改看板列" tabindex="-1">修改看板列 <a class="header-anchor" href="#修改看板列" aria-label="Permalink to &quot;修改看板列&quot;">​</a></h3><ol><li>进入&quot;项目管理&quot;</li><li>点击&quot;Status&quot;属性</li><li>Edit property → 添加/删除状态</li></ol><h3 id="创建自定义视图" tabindex="-1">创建自定义视图 <a class="header-anchor" href="#创建自定义视图" aria-label="Permalink to &quot;创建自定义视图&quot;">​</a></h3><ol><li>在数据库右上角点击&quot;+ Add a view&quot;</li><li>选择视图类型（Table、Gallery、Timeline）</li><li>设置筛选和排序规则</li></ol><h3 id="添加关联数据库" tabindex="-1">添加关联数据库 <a class="header-anchor" href="#添加关联数据库" aria-label="Permalink to &quot;添加关联数据库&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/linked → 选择要关联的数据库</span></span></code></pre></div><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><h3 id="自由设计师" tabindex="-1">自由设计师 <a class="header-anchor" href="#自由设计师" aria-label="Permalink to &quot;自由设计师&quot;">​</a></h3><ul><li>管理多个客户项目</li><li>跟踪工作时间和收入</li><li>存储合同和发票</li></ul><h3 id="设计团队" tabindex="-1">设计团队 <a class="header-anchor" href="#设计团队" aria-label="Permalink to &quot;设计团队&quot;">​</a></h3><ul><li>团队协作和任务分配</li><li>共享设计资源</li><li>项目进度透明化</li></ul><h3 id="设计学生" tabindex="-1">设计学生 <a class="header-anchor" href="#设计学生" aria-label="Permalink to &quot;设计学生&quot;">​</a></h3><ul><li>作品集项目管理</li><li>学习资源整理</li><li>灵感收集</li></ul><h2 id="进阶玩法" tabindex="-1">进阶玩法 <a class="header-anchor" href="#进阶玩法" aria-label="Permalink to &quot;进阶玩法&quot;">​</a></h2><h3 id="集成第三方工具" tabindex="-1">集成第三方工具 <a class="header-anchor" href="#集成第三方工具" aria-label="Permalink to &quot;集成第三方工具&quot;">​</a></h3><ul><li><strong>Figma</strong>：嵌入设计稿</li><li><strong>Google Calendar</strong>：同步日程</li><li><strong>Slack</strong>：通知提醒</li></ul><h3 id="使用-formula" tabindex="-1">使用 Formula <a class="header-anchor" href="#使用-formula" aria-label="Permalink to &quot;使用 Formula&quot;">​</a></h3><p>计算项目利润：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prop(&quot;收入&quot;) - prop(&quot;成本&quot;)</span></span></code></pre></div><h3 id="创建仪表盘" tabindex="-1">创建仪表盘 <a class="header-anchor" href="#创建仪表盘" aria-label="Permalink to &quot;创建仪表盘&quot;">​</a></h3><p>使用 Linked Database 创建统计面板：</p><ul><li>本月项目数量</li><li>本月收入</li><li>待完成任务</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 可以用手机管理吗？</strong><br> A: 可以！Notion 有 iOS 和 Android 客户端。</p><p><strong>Q: 可以分享给客户查看吗？</strong><br> A: 可以设置页面权限，分享给指定客户。</p><p><strong>Q: 数据会丢失吗？</strong><br> A: Notion 自动云同步，无需担心数据丢失。</p><hr><p><a href="/resources/">← 返回创作资源</a></p>',63)])])}const q=l(t,[["render",r]]);export{p as __pageData,q as default};
